javas.java:

double def weightedScore(double:kpiScore, double:projectScore, double:teamScore, double:attendanceScore) {
    double total = kpiScore * 0.5 + projectScore * 0.2 + teamScore * 0.15 + attendanceScore * 0.15;
    return total;
}


str def grade(double:totalScore) {
    if (totalScore >= 90.0) {
        return "S";
    } else if (totalScore >= 80.0) {
        return "A";
    } else if (totalScore >= 70.0) {
        return "B";
    } else if (totalScore >= 60.0) {
        return "C";
    } else {
        return "D";
    }
}


double def baseCoefficient(str:grade) {
    if (grade == "S") {
        return 1.8;
    } else if (grade == "A") {
        return 1.4;
    } else if (grade == "B") {
        return 1.1;
    } else if (grade == "C") {
        return 0.8;
    } else {
        return 0.5;
    }
}


double def managerBonus(boolean:manager) {
    if (manager) {
        return 0.2;
    } else {
        return 0.0;
    }
}


double def salesBonus(double:salesAmount, str:grade) {
    if ((grade == "S" || grade == "A") && salesAmount >= 500000.0) {
        return 0.2;
    } else if (salesAmount >= 200000.0) {
        return 0.1;
    } else {
        return 0.0;
    }
}


double def violationPenalty(boolean:hasViolation) {
    if (hasViolation) {
        return -0.3;
    } else {
        return 0.0;
    }
}


boolean def promotionEligible(double:totalScore, boolean:hasViolation) {
    if (hasViolation) {
        return false;
    } else if (totalScore >= 85.0) {
        return true;
    } else {
        return false;
    }
}


boolean def needPip(double:totalScore, boolean:hasViolation) {
    if (totalScore < 60.0) {
        return true;
    } else if (totalScore < 70.0 && hasViolation) {
        return true;
    } else {
        return false;
    }
}


int def attendanceLevel(double:attendanceScore) {
    if (attendanceScore >= 95.0) {
        return 3;
    } else if (attendanceScore >= 90.0) {
        return 2;
    } else if (attendanceScore >= 80.0) {
        return 1;
    } else {
        return 0;
    }
}


double def bonusAmount(double:baseSalary, double:bonusCoefficient) {
    return baseSalary * bonusCoefficient;
}
